args.command:
ls -la proto/api/v1 && python3 - <<'PY'
from pathlib import Path
for p in Path('proto/api/v1').rglob('*.proto'):
    for i,line in enumerate(p.read_text().splitlines(),1):
        if 'Transcribe' in line:
            print(f'{p}:{i}:{line}')
            for j,x in enumerate(p.read_text().splitlines()[max(0,i-4):i+2],max(1,i-3)):
                print(f'  {j}:{x}')
PY

